<?php
declare(strict_types=1);
require_once __DIR__ . '/../backend/db.php';
header_remove('Content-Type');
header('Content-Type: text/html; charset=utf-8');
$pdo=db();
$userId=isset($_SESSION['user_id'])?(int)$_SESSION['user_id']:0;
if(!$userId){ header('Location: ../frontend/'); exit; }
$userStmt=$pdo->prepare('SELECT id,full_name,email,role FROM users WHERE id=? LIMIT 1');$userStmt->execute([$userId]);$user=$userStmt->fetch();
if(!$user||$user['role']!=='admin'){http_response_code(403);echo '<h1>403</h1><p>Bu alan yalnızca RoadPass yöneticilerine açıktır.</p><a href="../frontend/">RoadPass’e dön</a>';exit;}
if(empty($_SESSION['admin_csrf']))$_SESSION['admin_csrf']=bin2hex(random_bytes(24));
$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!hash_equals((string)$_SESSION['admin_csrf'],(string)($_POST['csrf']??''))){$error='Güvenlik doğrulaması başarısız.';}
  else{
    $action=(string)($_POST['action']??'');
    try{
      if($action==='approve'){
        $id=(int)($_POST['id']??0);$pdo->beginTransaction();
        $stmt=$pdo->prepare('SELECT * FROM vehicle_model_suggestions WHERE id=? AND status="pending" FOR UPDATE');$stmt->execute([$id]);$suggestion=$stmt->fetch();
        if(!$suggestion)throw new RuntimeException('Bekleyen öneri bulunamadı.');
        $find=$pdo->prepare('SELECT id FROM vehicle_models WHERE brand_id=? AND LOWER(name)=LOWER(?) LIMIT 1');$find->execute([(int)$suggestion['brand_id'],$suggestion['model_name']]);$modelId=(int)($find->fetchColumn()?:0);
        if(!$modelId){$add=$pdo->prepare('INSERT INTO vehicle_models (brand_id,name,is_active) VALUES (?,?,1)');$add->execute([(int)$suggestion['brand_id'],$suggestion['model_name']]);$modelId=(int)$pdo->lastInsertId();}
        $pdo->prepare('UPDATE vehicle_model_suggestions SET status="approved",approved_model_id=?,admin_note=? WHERE id=?')->execute([$modelId,trim((string)($_POST['note']??''))?:null,$id]);
        $pdo->prepare('UPDATE vehicles SET model_id=? WHERE user_id=? AND brand_id=? AND LOWER(model)=LOWER(?) AND model_id IS NULL')->execute([$modelId,(int)$suggestion['user_id'],(int)$suggestion['brand_id'],$suggestion['model_name']]);
        $pdo->commit();$message='Model onaylandı ve kataloğa eklendi.';
      }elseif($action==='reject'){
        $id=(int)($_POST['id']??0);$pdo->prepare('UPDATE vehicle_model_suggestions SET status="rejected",admin_note=? WHERE id=? AND status="pending"')->execute([trim((string)($_POST['note']??''))?:'Katalog kurallarına uygun değil.',$id]);$message='Öneri reddedildi.';
      }elseif($action==='add_brand'){
        $typeId=(int)($_POST['vehicle_type_id']??0);$name=trim((string)($_POST['name']??''));if($typeId<1||mb_strlen($name)<2)throw new RuntimeException('Araç tipi ve marka adı gereklidir.');$pdo->prepare('INSERT INTO vehicle_brands (vehicle_type_id,name,is_active) VALUES (?,?,1)')->execute([$typeId,$name]);$message='Marka kataloğa eklendi.';
      }elseif($action==='add_model'){
        $brandId=(int)($_POST['brand_id']??0);$name=trim((string)($_POST['name']??''));if($brandId<1||mb_strlen($name)<2)throw new RuntimeException('Marka ve model adı gereklidir.');$pdo->prepare('INSERT INTO vehicle_models (brand_id,name,is_active) VALUES (?,?,1)')->execute([$brandId,$name]);$message='Model kataloğa eklendi.';
      }
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
  }
}
$types=$pdo->query('SELECT id,name_tr FROM vehicle_types WHERE is_active=1 ORDER BY sort_order')->fetchAll();
$brands=$pdo->query('SELECT b.id,b.name,vt.name_tr AS type_name FROM vehicle_brands b JOIN vehicle_types vt ON vt.id=b.vehicle_type_id WHERE b.is_active=1 ORDER BY vt.sort_order,b.name')->fetchAll();
$suggestions=$pdo->query('SELECT s.id,s.model_name,s.manufacture_year,s.fuel_type,s.body_type,s.status,s.created_at,u.full_name,u.email,b.name AS brand,vt.name_tr AS vehicle_type FROM vehicle_model_suggestions s JOIN users u ON u.id=s.user_id JOIN vehicle_brands b ON b.id=s.brand_id JOIN vehicle_types vt ON vt.id=s.vehicle_type_id ORDER BY FIELD(s.status,"pending","approved","rejected"),s.created_at DESC LIMIT 200')->fetchAll();
$counts=$pdo->query('SELECT (SELECT COUNT(*) FROM vehicle_brands WHERE is_active=1) brands,(SELECT COUNT(*) FROM vehicle_models WHERE is_active=1) models,(SELECT COUNT(*) FROM vehicle_model_suggestions WHERE status="pending") pending')->fetch();
function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RoadPass Katalog Yönetimi</title><link rel="icon" href="../frontend/assets/img/logo.svg"><style>
:root{--bg:#0f1115;--surface:#191d24;--surface2:#222730;--border:rgba(255,255,255,.09);--text:#fff;--muted:#9da4af;--green:#21e18a;--gold:#f5c96a;--red:#ff7180}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 90% 0,rgba(245,201,106,.08),transparent 30%),var(--bg);color:var(--text);font:14px Inter,system-ui,sans-serif}.shell{display:grid;grid-template-columns:250px 1fr;min-height:100vh}.side{padding:26px 20px;border-right:1px solid var(--border);background:#11151b}.brand{display:flex;align-items:center;gap:12px}.brand img{width:44px}.brand strong{letter-spacing:.12em}.side p{color:var(--muted);font-size:12px;line-height:1.6}.side a{display:block;margin-top:22px;padding:12px;border:1px solid var(--border);border-radius:12px;color:#fff;text-decoration:none}.main{padding:32px;max-width:1500px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.top h1{margin:0 0 7px}.top p{margin:0;color:var(--muted)}.user{text-align:right}.user small{display:block;color:var(--gold)}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin-bottom:20px}.metric,.card{background:linear-gradient(145deg,var(--surface),var(--surface2));border:1px solid var(--border);border-radius:18px;padding:18px}.metric small{color:var(--muted)}.metric strong{display:block;font-size:28px;margin-top:7px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-bottom:20px}.card h2{margin-top:0;font-size:17px}.form{display:grid;gap:11px}.form.two{grid-template-columns:1fr 1fr}.form label{display:grid;gap:6px;color:#cad0d9;font-size:12px}.form input,.form select,.form textarea{width:100%;padding:11px;border-radius:10px;border:1px solid var(--border);background:#11151b;color:#fff}.btn{border:0;border-radius:10px;padding:11px 14px;font-weight:700;cursor:pointer;background:var(--green);color:#062016}.btn.red{background:rgba(255,113,128,.12);color:#ff9ba6;border:1px solid rgba(255,113,128,.2)}.btn.gold{background:rgba(245,201,106,.13);color:var(--gold);border:1px solid rgba(245,201,106,.22)}.notice{padding:13px;border-radius:12px;margin-bottom:18px}.notice.ok{background:rgba(33,225,138,.08);border:1px solid rgba(33,225,138,.2);color:#7ff0b7}.notice.err{background:rgba(255,113,128,.08);border:1px solid rgba(255,113,128,.2);color:#ff9ba6}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:12px 10px;border-bottom:1px solid var(--border);text-align:left;vertical-align:top}.table th{font-size:10px;color:var(--muted);text-transform:uppercase}.table small{color:var(--muted);display:block;margin-top:4px}.status{padding:5px 8px;border-radius:999px;background:rgba(255,255,255,.06);font-size:10px}.status.pending{color:var(--gold)}.status.approved{color:var(--green)}.status.rejected{color:var(--red)}.actions form{display:grid;grid-template-columns:1fr auto auto;gap:7px}.actions input{min-width:150px;padding:8px;border-radius:8px;border:1px solid var(--border);background:#11151b;color:#fff}@media(max-width:900px){.shell{grid-template-columns:1fr}.side{display:none}.main{padding:18px}.grid,.metrics{grid-template-columns:1fr}.table-wrap{overflow:auto}.actions form{grid-template-columns:1fr}}
</style></head><body><div class="shell"><aside class="side"><div class="brand"><img src="../frontend/assets/img/logo.svg" alt=""><div><strong>ROADPASS</strong><small>KATALOG YÖNETİMİ</small></div></div><p>Marka ve model kataloğunu yönetin, kullanıcıların “Modelimi bulamadım” önerilerini inceleyin.</p><a href="../frontend/">← RoadPass’e dön</a></aside><main class="main"><header class="top"><div><h1>Araç Kataloğu</h1><p>Revizyon 4 yönetici prototipi</p></div><div class="user"><strong><?=e($user['full_name'])?></strong><small>Yönetici</small></div></header><?php if($message):?><div class="notice ok"><?=e($message)?></div><?php endif?><?php if($error):?><div class="notice err"><?=e($error)?></div><?php endif?><section class="metrics"><div class="metric"><small>Aktif marka</small><strong><?=$counts['brands']?></strong></div><div class="metric"><small>Aktif model</small><strong><?=$counts['models']?></strong></div><div class="metric"><small>Bekleyen öneri</small><strong><?=$counts['pending']?></strong></div></section><div class="grid"><section class="card"><h2>Marka Ekle</h2><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e($_SESSION['admin_csrf'])?>"><input type="hidden" name="action" value="add_brand"><label>Araç tipi<select name="vehicle_type_id" required><?php foreach($types as $t):?><option value="<?=$t['id']?>"><?=e($t['name_tr'])?></option><?php endforeach?></select></label><label>Marka adı<input name="name" maxlength="100" required></label><button class="btn">Markayı Ekle</button></form></section><section class="card"><h2>Model Ekle</h2><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e($_SESSION['admin_csrf'])?>"><input type="hidden" name="action" value="add_model"><label>Marka<select name="brand_id" required><?php foreach($brands as $b):?><option value="<?=$b['id']?>"><?=e($b['type_name'].' · '.$b['name'])?></option><?php endforeach?></select></label><label>Model adı<input name="name" maxlength="120" required></label><button class="btn">Modeli Ekle</button></form></section></div><section class="card"><h2>Kullanıcı Model Önerileri</h2><div class="table-wrap"><table class="table"><thead><tr><th>Durum</th><th>Araç</th><th>Öneren</th><th>Detay</th><th>Tarih</th><th>İşlem</th></tr></thead><tbody><?php if(!$suggestions):?><tr><td colspan="6">Öneri bulunmuyor.</td></tr><?php endif?><?php foreach($suggestions as $s):?><tr><td><span class="status <?=e($s['status'])?>"><?=e($s['status'])?></span></td><td><strong><?=e($s['brand'].' '.$s['model_name'])?></strong><small><?=e($s['vehicle_type'])?></small></td><td><?=e($s['full_name'])?><small><?=e($s['email'])?></small></td><td><?=e(($s['manufacture_year']?:'—').' · '.($s['fuel_type']?:'—').' · '.($s['body_type']?:'—'))?></td><td><?=e($s['created_at'])?></td><td class="actions"><?php if($s['status']==='pending'):?><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['admin_csrf'])?>"><input type="hidden" name="id" value="<?=$s['id']?>"><input name="note" placeholder="Yönetici notu"><button class="btn gold" name="action" value="approve">Onayla</button><button class="btn red" name="action" value="reject">Reddet</button></form><?php else:?>—<?php endif?></td></tr><?php endforeach?></tbody></table></div></section></main></div></body></html>
